(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(y * 0.018 + t * 0.3) * 12 + Math.cos((x + y) * 0.012 - t * 0.2) * 8;
  const w1y = Math.cos(x * 0.015 - t * 0.25) * 12 + Math.sin((x - y) * 0.014 + t * 0.35) * 8;
  const mx = x + w1x, my = y + w1y;
  const w2x = Math.sin(my * 0.025 - t * 0.4) * 6 + Math.cos(mx * 0.02 + t * 0.3) * 5;
  const w2y = Math.cos(mx * 0.022 + t * 0.35) * 6 + Math.sin(my * 0.018 - t * 0.45) * 5;
  const sx = mx + w2x, sy = my + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*40, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*50, 0.085, 1.8]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.sin(d*f*0.5 - t*sp*0.3 + 3.0);
  }
  const act = aS/8, inh = iS/8, harm = hS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15 + Math.sin(sx*0.05-sy*0.07+t*1.8)*0.1;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.07-ang*2+t*0.8))*0.33;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const fine = Math.sin(sx*0.3+t*2)*Math.sin(sy*0.25-t*1.7)*0.12;
